const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    var aleppo = ee.Geometry.Point(37.1343, 36.2021).buffer(10000); // 10km buffer around Aleppo
    var start2012 = '2012-01-01';
    var end2012 = '2012-12-31';
    var start2016 = '2016-01-01';
    var end2016 = '2016-12-31';

    // 2. Data Acquisition - VIIRS Monthly Nighttime Lights
    var viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
        .select('avg_rad'); // average radiance band

    var col2012 = viirs.filterDate(start2012, end2012).filterBounds(aleppo);
    var col2016 = viirs.filterDate(start2016, end2016).filterBounds(aleppo);

    // Check collection sizes
    var size2012 = col2012.size().getInfo();
    var size2016 = col2016.size().getInfo();
    console.log('2012 Images:', size2012);
    console.log('2016 Images:', size2016);

    // If either collection is empty, try alternative collection (DMSP for 2012)
    if (size2012 === 0 || size2016 === 0) {
        // Try DMSP for 2012 if VIIRS is empty
        if (size2012 === 0) {
            var dmsp2012 = ee.ImageCollection('NOAA/DMSP-OLS/NIGHTTIME_LIGHTS')
                .filterDate('2012-01-01', '2012-12-31')
                .filterBounds(aleppo)
                .select('stable_lights');
            var dmspSize = dmsp2012.size().getInfo();
            console.log('DMSP 2012 Images (fallback):', dmspSize);
            if (dmspSize > 0) {
                col2012 = dmsp2012;
                size2012 = dmspSize;
            } else {
                console.log('No data for 2012.');
                console.log('<answer>C1</answer>');
                return;
            }
        }
        if (size2016 === 0) {
            console.log('No data for 2016.');
            console.log('<answer>C1</answer>');
            return;
        }
    }

    // 3. Processing - Create composites (mean) and count valid pixels
    var img2012 = col2012.mean();
    var img2016 = col2016.mean();

    // Count valid pixels (pixels > 0, since radiance can be 0)
    var count2012 = img2012.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aleppo,
        scale: 1000,
        maxPixels: 1e9
    }).get('avg_rad').getInfo();

    var count2016 = img2016.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aleppo,
        scale: 1000,
        maxPixels: 1e9
    }).get('avg_rad').getInfo();

    console.log('Valid pixels 2012:', count2012);
    console.log('Valid pixels 2016:', count2016);

    if (count2012 === 0 || count2016 === 0) {
        console.log('No valid pixels after processing.');
        console.log('<answer>C2</answer>');
        return;
    }

    // 4. Calculation - Mean radiance
    var mean2012 = img2012.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: aleppo,
        scale: 1000,
        maxPixels: 1e9
    }).get('avg_rad').getInfo();

    var mean2016 = img2016.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: aleppo,
        scale: 1000,
        maxPixels: 1e9
    }).get('avg_rad').getInfo();

    console.log('Mean radiance 2012:', mean2012);
    console.log('Mean radiance 2016:', mean2016);

    // 5. Validation & Final Answer
    if (mean2012 === null || mean2016 === null || 
        isNaN(mean2012) || isNaN(mean2016) || 
        mean2012 < 0 || mean2016 < 0) { // radiance shouldn't be negative
        console.log('Invalid calculation result.');
        console.log('<answer>C3</answer>');
        return;
    }

    // Check if 2016 is less than 2012
    if (mean2016 < mean2012) {
        console.log('Nighttime light intensity decreased.');
        console.log('<answer>A</answer>');
    } else {
        console.log('Nighttime light intensity did not decrease.');
        console.log('<answer>B</answer>');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
